"""Word Break II — memoised recursion returning every sentence for a suffix.

Caching per start index turns the exponential re-exploration into one pass per
distinct suffix.

Time: O(n^2 * 2^n) worst case   Space: O(n * results)
"""
from functools import lru_cache
from typing import List


class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        words = set(wordDict)

        @lru_cache(maxsize=None)
        def solve(start: int):
            if start == len(s):
                return ("",)
            sentences = []
            for end in range(start + 1, len(s) + 1):
                piece = s[start:end]
                if piece in words:
                    for rest in solve(end):
                        sentences.append(piece if not rest else piece + " " + rest)
            return tuple(sentences)

        return list(solve(0))
